// Camera/input adapter only. Combat continues receiving rival-relative x/z.
export const SIDE_HYSTERESIS=.15; // Playtest guess: normalized screen-right projection (~8.6 degrees).
export const controlsFromSearch=s=>['side','lockon'].includes(new URLSearchParams(s).get('controls'))?new URLSearchParams(s).get('controls'):'';
export const controlsCamera=(scheme,saved)=>scheme==='side'?'duel':scheme==='lockon'?'lock':saved;
export function cameraRight(camera){const e=camera?.matrixWorld?.elements,n=e?Math.hypot(e[0],e[2]):0;return n>1e-8?{x:e[0]/n,z:e[2]/n}:{x:1,z:0};}
export function createControlMapper(scheme){let sign=1,held=false,initialized=false,lastRaw={x:0,z:0};return {reset(){sign=1;held=false;initialized=false;},get sign(){return sign;},get raw(){return lastRaw;},map(raw,self,rival,right={x:1,z:0},directionHeld=Math.hypot(raw.x,raw.z)>1e-6){lastRaw={...raw};if(scheme!=='side')return {...raw,x:-raw.z,z:raw.x};const dx=(rival?.x||0)-(self?.x||0),dz=(rival?.z||0)-(self?.z||0),d=Math.hypot(dx,dz),n=Math.hypot(right.x,right.z)||1,projection=d?(dx*right.x+dz*right.z)/(d*n):0;const active=directionHeld;
// Keep BOTH axes stable until all directional inputs return to neutral; diagonals share one latch.
if(!held||!active){if(projection>SIDE_HYSTERESIS)sign=1;else if(projection<-SIDE_HYSTERESIS)sign=-1;else if(!initialized&&projection!==0)sign=Math.sign(projection);initialized=true;}held=active;return {...raw,x:raw.x*sign,z:raw.z*sign};}};}
export function schemeText(scheme,sign=1){return scheme==='side'?`SIDE CONTROLS · Left/right approach or retreat · Up/down circle into/out of screen · Toward key: ${sign>0?'RIGHT':'LEFT'} · Release directions to change sides`:'LOCK-ON CONTROLS · Up approaches · Down retreats · Left/right circle';}
export function previewBindings(scheme,sign,bindings,controller=false){const buttons=['Left','Right','Up','Down','A / Cross','B / Circle','X / Square','Left bumper','Right bumper','Y / Triangle'],base=controller?buttons.map(x=>[x]):bindings[0],order=scheme==='side'?(sign>0?[2,3,1,0]:[3,2,0,1]):[0,1,2,3];return [[...order.map(i=>base[i]),...base.slice(4)],bindings[1]];}
export function controlsManual(scheme,sign,bindings,keyName,grab={}){const b=bindings[0].map(keys=>keys.map(keyName).join(' / ')),side=scheme==='side',logical=previewBindings(scheme,sign,bindings)[0].map(keys=>keys.map(keyName).join(' / ')),[left,right,toward,away]=logical;
return `<div class="eyebrow">FIELD MANUAL / ${side?'SIDE':'LOCK-ON'} CONTROLS PREVIEW</div><h2>MOVE WITH THE CAMERA.</h2><p>${schemeText(scheme,sign)}</p><p>${side?'The Duel camera is forced for this match. Left/right use the rival’s screen side, not the player number. Up moves into the screen; down moves out. Both axes keep their mapping while any direction is held. Release all directions after a side swap. Near screen alignment, a small dead band keeps the last side.':'The Lock-on camera is forced for this match. Your normal opponent-relative directions never flip.'} Saved camera options are unchanged.</p><p>Your bindings: ${b.map((key,i)=>`${['Screen left','Screen right','Screen up','Screen down','Attack / charge','Guard','Capture','Launch','Pursuit','Burst'][i]}: ${key}`).join(' · ')}. Controller directions follow the same scheme; attack A/Cross, guard B/Circle, capture X/Square, launch LB, pursuit RB, Burst Y/Triangle.</p><h3>CURRENT DIRECTIONAL COMMANDS</h3><p>These keys reflect the current side. On side controls, reversing screen sides swaps both horizontal and circle command directions after release.</p><table class="controls"><tr><td>Toward / away</td><td>${toward} / ${away}</td></tr><tr><td>Forward / retreat special</td><td>${toward} / ${away} + tap ${b[4]}</td></tr><tr><td>Third signature</td><td>${left} + tap ${b[4]}</td></tr><tr><td>Capture</td><td>${b[6]}${grab.deliberate?'':` or ${right} + tap ${b[4]}`}</td></tr><tr><td>Double-tap then attack: pursuit / Burst</td><td>${toward} / ${away} + ${b[4]}</td></tr><tr><td>Double-tap then attack: launcher / crossover</td><td>${right} / ${left} + ${b[4]}</td></tr><tr><td>Double-tap then guard: jump</td><td>${left} + ${b[5]}</td></tr><tr><td>Toward + guard: circle behind</td><td>${toward} + ${b[5]}</td></tr></table><p>Move V2: double-tap ${side?b[2]+' or '+b[3]:b[0]+' or '+b[1]} to sidestep; toward to dash, away to backdash. Steps require two taps within 12 frames; attack/guard commands retain 18 frames. No attack/guard on the initiating step taps. During a step, attack or guard retains the existing directional command. Step recovery is six frames; guard cannot start during it.</p><p>Tap attack for a close strike or distant shot. Neutral hold charges; release directional holds for stock specials. Extra attack taps during startup select existing follow-ups. Attack and guard timings, hitboxes, capture-break rules and power costs are unchanged. ${grab.hold?'Grab hold preview requires eight frames of the capture direction before attack.':''}</p><p>Training input history shows physical arrows for this scheme. Guided lessons use your current side and bindings. For stagger recovery alternate the two circle keys; tap a direction while down to roll, guard for a quick rise, or fresh airborne guard to recover. P2 uses arrow keys and Numpad 1–6 / 1–6; each player gets their own side latch. Menu controls and rebinding remain unchanged.</p>`;}
